// Combine the geolocation + timezone lookups into one clean lead profile,
// and decide whether it's currently business hours (9am-6pm) at the lead's location.
const geo = $('Fetch IP Geolocation Data').item.json;
const lead = $('Check IP Address Validity').item.json;
const timeZone = $json.time_zone || {};

const location = geo.location || {};
const asn = geo.asn || {};

// time_zone.current_time looks like "2026-09-07 16:55:30.494+0200" - pull the local hour
// straight out of the string instead of trusting Date parsing across timezones.
const match = (timeZone.current_time || '').match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2})/);
const localHour = match ? parseInt(match[4], 10) : null;
const isBusinessHours = localHour !== null && localHour >= 9 && localHour < 18;

let nextContactWindow = null;
if (match && !isBusinessHours) {
  const [, y, mo, d] = match;
  const rollsToNextDay = localHour >= 18;
  const day = parseInt(d, 10) + (rollsToNextDay ? 1 : 0);
  nextContactWindow = `${y}-${mo}-${String(day).padStart(2, '0')} 09:00 ${timeZone.current_tz_abbreviation || ''}`.trim();
}

return {
  json: {
    ip: lead.ip,
    name: lead.name,
    email: lead.email,
    company_name: lead.company,
    network_organization: asn.organization || '',
    location: {
      city: location.city || '',
      region: location.state_prov || '',
      country: location.country_name || '',
      country_code: location.country_code2 || '',
      continent: location.continent_name || '',
    },
    timezone: timeZone.name || '',
    local_time_now: timeZone.current_time || '',
    utc_offset_hours: timeZone.offset_with_dst,
    is_business_hours_now: isBusinessHours,
    recommended_contact: isBusinessHours ? 'contact_now' : 'schedule_for_local_morning',
    next_local_contact_window: nextContactWindow,
  },
};

// Normalize the incoming payload and do a quick IPv4 / IPv6 syntax check
// before we ever spend an API credit on it.
const ip = $json.body.ip || '';

const ipv4 = /^(25[0-5]|2[0-4]\d|1\d{2}|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d{2}|[1-9]?\d)){3}$/;
const ipv6 = /^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^(([0-9a-fA-F]{1,4}:){1,7}|:)(:[0-9a-fA-F]{1,4}){1,7}$|^::$/;

const ipIsValid = ipv4.test(ip) || ipv6.test(ip);

return {
  json: {
    ip,
    name: $json.body.name || '',
    email: $json.body.email || '',
    company: $json.body.company || '',
    ipIsValid,
  },
};
